<template><view class="page"><view v-if="error" class="error">{{ error }}<button @click="refresh">刷新任务</button></view><view v-if="!task" class="empty">正在加载任务…</view><template v-else><view class="hero"><view class="title">{{ task.title }}</view><view class="muted">{{ task.store_name }} · {{ task.business_date }}</view><view class="status">{{ taskStatus(task.status) }} · 进行中 {{ task.total-task.completed }} · 已完成 {{ task.completed }}/{{ task.total }}</view><view class="muted">{{ task.description }}</view><button class="refresh" :disabled="busy" @click="refresh">刷新共同进度（保留未保存内容）</button></view><view v-if="task.submissions.length" class="question receipt"><view class="q-title">审核回执 · 第 {{task.submissions[0].version}} 版</view><view class="receipt-state">{{ {pending:'待审核',rejected:'审核驳回',approved:'审核通过'}[task.submissions[0].status] }}</view><view v-if="task.submissions[0].status==='pending'" class="muted">提交已收到，等待审核。刷新可查看最新回执。</view><template v-else><view class="muted">审核人：{{task.submissions[0].reviewed_name}} · {{fmt(task.submissions[0].reviewed_at)}}</view><view class="opinion">备注：{{task.submissions[0].review_note||'无备注'}}</view><view v-if="task.submissions[0].status==='rejected'" class="muted">请按备注修改并重新提交；原回执保留在历史记录中。</view></template></view><view class="auto-store">门店名称 <text>{{ task.store_name }}</text><view class="muted">由系统自动带出，无需填写</view></view><view class="hint">全店共享同一份进度。单人项由任意一名成员完成；多人项允许共同补充。只能修改自己保存的内容。</view><view v-for="(q,index) in task.results" :key="q.id" class="question"><view class="q-title"><text v-if="q.required" class="required">*</text>{{ String(index+1).padStart(2,'0') }} {{ q.title }}<text class="badge">{{ q.complete?'已完成':'待完成' }}</text></view><view class="muted">{{ q.execution_mode==='single'?'单人完成':'多人共同完成' }}<text v-if="q.owner"> · {{ q.complete?'实际完成人':'正在填写' }}：{{ q.owner.name }}</text><text v-else-if="q.complete"> · 实际完成人：{{ (q.completed_by||[]).map(a=>a.name).join('、') }}</text></view><TaskInstructions :text="q.description" :images="q.guide_images||[]" @photo="showPhoto"/><view v-if="q.type==='photo'" class="muted">全体合计 {{ q.min }}–{{ q.max }} 张，现有 {{ q.photos.length }} 张</view><view v-if="q.conflict" class="error">多人答案不一致，请协调后修改自己的答案。</view><view v-for="a in q.contributions" :key="a.id" class="contribution"><view class="muted">{{ a.user_name }} · {{ fmt(a.created_at) }}</view><view v-if="a.response.value">{{ displayValue(q,a.response.value) }}</view><view v-for="(image,i) in a.response.images" :key="image" class="image-link" @click="showPhoto(image)">查看照片 {{ i+1 }} →</view></view><template v-if="canAnswer(q)"><view class="own-label">我的填写</view><template v-if="q.type==='photo'"><view v-for="(image,i) in answers[q.id]?.images" :key="image" class="my-photo"><text @click="showPhoto(image)">照片 {{ i+1 }} · 查看</text><text class="remove" @click="answers[q.id].images.splice(i,1)">移除</text></view><button :disabled="busy||(answers[q.id]?.images.length||0)>=q.max" @click="choose(q)">拍照 / 选择照片</button></template><radio-group v-else-if="q.type==='choice'" @change="answers[q.id].value=$event.detail.value"><label v-for="option in q.options" :key="option" class="radio"><radio :value="option" :checked="answers[q.id]?.value===option" color="#d94f2b"/>{{ option }}</label><view class="clear" @click="answers[q.id].value=''">清空我的答案</view></radio-group><picker v-else-if="q.type==='dropdown'" :range="q.options" :value="Math.max(0,q.options.indexOf(answers[q.id]?.value))" @change="answers[q.id].value=q.options[Number($event.detail.value)]"><view class="own-label">{{ answers[q.id]?.value || '点击选择选项' }}</view></picker><checkbox-group v-else-if="q.type==='multiple'" @change="answers[q.id].value=JSON.stringify($event.detail.value)"><label v-for="option in q.options" :key="option" class="radio"><checkbox :value="option" :checked="multi(answers[q.id]?.value).includes(option)" color="#d94f2b"/>{{ option }}</label></checkbox-group><picker v-else-if="q.type==='date'" mode="date" :value="answers[q.id]?.value" @change="answers[q.id].value=$event.detail.value"><view class="own-label">{{ answers[q.id]?.value || '点击选择日期' }}</view></picker><input v-else-if="q.type==='number'" v-model="answers[q.id].value" type="digit" placeholder="请输入数值"/><textarea v-else v-model="answers[q.id].value" :maxlength="q.maxLength||2000" :placeholder="q.placeholder||'请输入文字说明'" auto-height/><button class="save" :disabled="busy" @click="save(q)">保存本项</button></template></view><button v-if="editable" class="primary" :disabled="busy" @click="submit">提交整份任务审核</button><view v-if="can('store-tasks.review')&&task.status==='pending'" class="question"><view class="q-title">审核第 {{ task.submissions[0].version }} 版</view><radio-group @change="reviewDecision=$event.detail.value"><label class="radio"><radio value="rejected" :checked="reviewDecision==='rejected'" color="#d94f2b"/>审核驳回</label><label class="radio"><radio value="approved" :checked="reviewDecision==='approved'" color="#d94f2b"/>审核通过</label></radio-group><view class="muted">先选择审核状态；驳回必须填写备注，通过可选填。</view><textarea v-model="note" maxlength="1000" auto-height :disabled="!reviewDecision||busy" :placeholder="reviewDecision?'审核备注（驳回必填）':'请先选择审核状态'"/><button :disabled="busy||!reviewDecision||(reviewDecision==='rejected'&&!note.trim())" @click="review">提交审核结果</button></view><view class="section-title">提交与审核历史</view><view v-if="!task.submissions.length" class="muted">尚未提交审核</view><view v-for="record in task.submissions" :key="record.id" class="question"><view class="q-title" @click="expanded=expanded===record.id?null:record.id">第 {{ record.version }} 版 · {{ taskStatus(record.status) }} ▾</view><view class="muted">{{ record.submitted_name }} · {{ fmt(record.submitted_at) }}</view><view class="opinion">{{ record.reviewed_name||'待审核' }}：{{ record.review_note||'暂无意见' }}</view><view v-if="expanded===record.id"><view v-for="q in record.snapshot" :key="q.id" class="history-q"><view>{{ q.title }}</view><view class="muted">{{ q.execution_mode==='single'?'单人完成':'多人共同完成' }}<text v-if="q.owner"> · {{ q.complete?'实际完成人':'正在填写' }}：{{ q.owner.name }}</text><text v-else-if="q.complete"> · 实际完成人：{{ (q.completed_by||[]).map(a=>a.name).join('、') }}</text></view><TaskInstructions :text="q.description" :images="q.guide_images||[]" @photo="showPhoto"/><view v-for="a in q.contributions" :key="a.id"><view class="muted">{{ a.user_name }} · {{ displayValue(q,a.response.value) }}</view><view v-for="(image,i) in a.response.images" :key="image" class="image-link" @click="showPhoto(image)">历史照片 {{ i+1 }} →</view></view></view></view></view></template><view v-if="photo" class="overlay" @click="photo=''"><image :src="photo" mode="aspectFit"/><view>点击关闭</view></view></view></template>
<script setup>
import {ref,reactive,computed} from 'vue'
import {onLoad,onShow,onHide,onUnload,onPullDownRefresh} from '@dcloudio/uni-app'
import api from '../../common/api'
import TaskInstructions from '../../components/TaskInstructions.vue'
import {taskStatus,imageData} from '../../common/task-context'
const reviewDecision=ref(''),ready=ref(false)
const task=ref(null),config=ref({}),answers=reactive({}),error=ref(''),busy=ref(false),note=ref(''),photo=ref(''),expanded=ref(null);let id=0
const can=p=>(config.value.permissions||[]).some(v=>v==='*'||v===p),editable=computed(()=>task.value&&can('store-tasks.execute')&&!['pending','approved'].includes(task.value.status))
const canAnswer=q=>editable.value&&(q.execution_mode!=='single'||!q.owner||q.owner.id===config.value.user_id)
let timer,fetchSequence=0,visible=false
function stopPolling(){visible=false;clearInterval(timer);fetchSequence++}
function startPolling(){visible=true;clearInterval(timer);timer=setInterval(()=>{if(ready.value&&!busy.value)detail(false).catch(e=>{error.value=e.message||'进度刷新失败'})},5000)}
function multi(v){try{return JSON.parse(v||'[]')}catch{return []}}
function displayValue(q,v){return q.type==='multiple'?multi(v).join('、'):v}
const fmt=s=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):''
async function attempt(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message||'操作失败，请刷新任务后重试'}finally{busy.value=false}}
async function detail(reset=true){const request=++fetchSequence,previous=task.value?.submissions[0]?.id;const latest=(await api.taskDetail(id)).task;if(request!==fetchSequence)return;task.value=latest;if(previous!==task.value.submissions[0]?.id){reviewDecision.value='';note.value=''};for(const q of task.value.results){if(reset||!answers[q.id]){const own=q.contributions.find(a=>a.user_id===config.value.user_id);answers[q.id]=JSON.parse(JSON.stringify(own?.response||{value:'',images:[]}))}}}
async function refresh(){if(busy.value)return;await attempt(()=>detail(false))}
onLoad(async options=>{id=Number(options.id);await attempt(async()=>{config.value=await api.taskConfig();await detail();ready.value=true})})
onShow(()=>{startPolling();if(ready.value)refresh()})
onHide(stopPolling);onUnload(stopPolling)
onPullDownRefresh(async()=>{await refresh();uni.stopPullDownRefresh()})
function choose(q){if(busy.value||!canAnswer(q))return;uni.chooseImage({count:1,sizeType:['compressed'],sourceType:['album','camera'],success:async r=>{await attempt(async()=>{const data=await imageData(r.tempFilePaths[0]);const file=await api.taskUpload(id,{data});answers[q.id].images.push(file.path)})}})}
async function showPhoto(path){await attempt(async()=>{photo.value=(await api.taskPhoto(path)).data})}
async function save(q){if(busy.value||!canAnswer(q))return;await attempt(async()=>{await api.taskAnswer(id,{question_id:q.id,revision:task.value.revision,...answers[q.id]});await detail(false);answers[q.id]=JSON.parse(JSON.stringify(task.value.results.find(r=>r.id===q.id).contributions.find(a=>a.user_id===config.value.user_id).response));uni.showToast({title:'已保存'})})}
function dirty(){return task.value.results.some(q=>canAnswer(q)&&JSON.stringify(answers[q.id])!==JSON.stringify(q.contributions.find(a=>a.user_id===config.value.user_id)?.response||{value:'',images:[]}))}
function submit(){if(dirty()){error.value='还有未保存的填写，请先点击对应题目的“保存本项”。';return}uni.showModal({title:'提交审核',content:'提交后整份任务冻结，审核退回后才能修改。确认提交？',success:r=>{if(r.confirm)attempt(async()=>{await api.taskSubmit(id,{revision:task.value.revision});await detail();uni.showToast({title:'已提交审核'})})}})}
async function review(){await attempt(async()=>{if(!['approved','rejected'].includes(reviewDecision.value))throw new Error('请先选择审核状态');if(reviewDecision.value==='rejected'&&!note.value.trim())throw new Error('审核驳回必须填写备注');await api.taskReview(id,{status:reviewDecision.value,note:note.value,version:task.value.submissions[0].version});reviewDecision.value='';note.value='';await detail();uni.showToast({title:'审核已保存'})})}
</script>
<style scoped>.receipt{margin-top:24rpx;border-left:6rpx solid #d94f2b}.receipt-state{font-size:30rpx;font-weight:600;margin:12rpx 0;color:#d94f2b}.receipt .opinion{white-space:pre-wrap}.page{padding:28rpx}.hero{background:#fff1e9;border-radius:24rpx;padding:30rpx}.refresh{font-size:24rpx;background:#fff;color:#d94f2b;margin-top:22rpx}.title{font-size:40rpx;font-weight:700;margin-bottom:16rpx}.muted{font-size:24rpx;color:#8b949c;line-height:1.8}.status{margin:22rpx 0;color:#d94f2b;font-size:28rpx}.auto-store{padding:28rpx;background:#fff;border-radius:20rpx;margin-top:24rpx;font-size:28rpx}.auto-store text{display:block;font-weight:600;margin:12rpx 0}.hint{font-size:25rpx;line-height:1.8;color:#8b949c;padding:26rpx 4rpx}.question{background:#fff;border-radius:22rpx;padding:28rpx;margin-bottom:24rpx}.q-title{font-size:29rpx;font-weight:600;line-height:1.7;margin-bottom:12rpx}.required{color:#d94f2b;margin-right:8rpx}.badge{color:#7c8891;float:right;font-size:22rpx;font-weight:400}.contribution{border-left:4rpx solid #e4e9e6;padding:10rpx 18rpx;margin-top:18rpx;font-size:27rpx}.image-link,.remove,.clear{color:#d94f2b;font-size:25rpx;padding:12rpx 0}.own-label{font-size:24rpx;color:#79848c;margin:24rpx 0 12rpx}.my-photo{display:flex;justify-content:space-between;align-items:center;font-size:26rpx}.radio{display:flex;align-items:center;padding:18rpx 0;font-size:28rpx}.save{background:#fff1e9;color:#d94f2b;margin-top:20rpx;font-size:26rpx}.primary{background:#d94f2b;color:#fff;font-size:28rpx}.question button{font-size:26rpx}.question input,.question textarea{box-sizing:border-box;width:100%;background:#f5f6f8;border-radius:14rpx;padding:20rpx;font-size:28rpx;margin:16rpx 0}.section-title{font-size:30rpx;font-weight:600;margin:40rpx 0 24rpx}.opinion{font-size:27rpx;line-height:1.8;margin-top:16rpx}.history-q{border-top:1px solid #f1f2f4;padding:22rpx 0;font-size:27rpx}.review-buttons{display:flex;gap:20rpx}.review-buttons button{flex:1;color:#d94f2b}.error{color:#c34530;font-size:26rpx;padding:22rpx 0}.empty{text-align:center;padding:80rpx}.overlay{position:fixed;inset:0;background:rgba(0,0,0,.85);z-index:99;display:flex;align-items:center;justify-content:center;flex-direction:column;color:#fff;font-size:25rpx}.overlay image{width:94vw;height:75vh;margin-bottom:20rpx}</style>
